/bin/zsh -lc "python3 - <<'PY'
import pathlib,json,re,difflib
data=json.loads(\"{\\\"summaries\\\":{\\\"author\\\":\\\"Write or harden a plan draft from a brief using an author session.\\\",\\\"autopilot\\\":\\\"Manage delegated run approvals, decisions, budgets, and activity records.\\\",\\\"block\\\":\\\"Manage block worktrees, ownership, reviews, acceptance evidence, and closure.\\\",\\\"context\\\":\\\"Build a context pack for a block in a run.\\\",\\\"doctor\\\":\\\"Check the project configuration, tools, credentials, and runtime setup.\\\",\\\"facts\\\":\\\"Build and validate a facts sheet from a brief and project sources.\\\",\\\"gates\\\":\\\"Detect and run project gates or check secrets, scope, acceptance, and transcripts.\\\",\\\"help\\\":\\\"List the available CLI verbs and shared command guidance.\\\",\\\"init\\\":\\\"Configure a project and install the skill for selected harnesses.\\\",\\\"jev\\\":\\\"Ask a recorded decision question through the Jev service.\\\",\\\"keys\\\":\\\"Store, list, test, or remove named credential references.\\\",\\\"land\\\":\\\"Provide the block landing implementation used by block land.\\\",\\\"ledger\\\":\\\"Read calibration and ledger history or record outcomes, spend, and outside reviews.\\\",\\\"list\\\":\\\"List the recorded skill installations.\\\",\\\"logs\\\":\\\"Read, summarize, clear, or report local CLI errors.\\\",\\\"models\\\":\\\"List provider model catalogs and optionally refresh them from local CLI caches.\\\",\\\"native-status\\\":\\\"Convert cached daemon records and rows from standard input into run status JSON.\\\",\\\"outcome\\\":\\\"Seal, validate, or record a specialist outcome file.\\\",\\\"pipeline\\\":\\\"Show pipeline step status or list the steps ready to run.\\\",\\\"plan\\\":\\\"Check a plan against its facts, project rules, and recorded decisions.\\\",\\\"proof\\\":\\\"Manage proof tiers, isolated exports, locks, restoration, and red-green evidence.\\\",\\\"remove\\\":\\\"Remove recorded skill installations for a harness or scope.\\\",\\\"report\\\":\\\"Display or export project ledger reports.\\\",\\\"resolve\\\":\\\"Show the provider, model, effort, fallbacks, and CLI resolved for a level.\\\",\\\"review\\\":\\\"Review changed files against acceptance criteria or stated intent.\\\",\\\"review-file\\\":\\\"Queue file reviews, wait for results, or check review evidence after a rebase.\\\",\\\"run\\\":\\\"Start, inspect, reload, or end a run and manage its workers.\\\",\\\"s2\\\":\\\"Answer a decision packet using a System 2 session.\\\",\\\"spawn\\\":\\\"Run a session at a selected level and role from a brief.\\\",\\\"status\\\":\\\"Show active runs, block progress, review gates, and spend.\\\",\\\"sweep\\\":\\\"Report stale processes and optionally stop those proven stale.\\\",\\\"tools\\\":\\\"List detected tools or install selected tools after confirmation.\\\",\\\"upgrade\\\":\\\"Refresh recorded skill installations from a skill source.\\\",\\\"validate\\\":\\\"Validate project configuration and pipeline definitions.\\\",\\\"version\\\":\\\"Print the package name and version.\\\"},\\\"newUsage\\\":{\\\"help\\\":\\\"usage: code-forge help\\\\n\\\",\\\"land\\\":\\\"usage: code-forge land\\\\n  Used internally by code-forge block land; this module has no standalone handler.\\\\n\\\",\\\"models\\\":\\\"usage: code-forge models [--refresh --from-cli-caches]\\\\n\\\",\\\"native-status\\\":\\\"usage: code-forge native-status\\\\n  Internal daemon companion: reads JSON records and rows from standard input.\\\\n\\\",\\\"resolve\\\":\\\"usage: code-forge resolve <L0|L1|L2|L3>\\\\n\\\",\\\"validate\\\":\\\"usage: code-forge validate [--file <path>]\\\\n\\\",\\\"version\\\":\\\"usage: code-forge version\\\\n\\\"},\\\"subUsage\\\":{\\\"run\\\":{\\\"start\\\":\\\"usage: code-forge run start [--cwd <dir>] [--run <id>] [--engine <e>] [--worker-pid <pid>] [--mode plan|brief]\\\\nusage: code-forge run start --add-worker --run <id>\\\\nusage: code-forge run start --reattach --run <id> [--worker-pid <pid>]\\\\n\\\",\\\"status\\\":\\\"usage: code-forge run status --run <id>\\\\n\\\",\\\"reload\\\":\\\"usage: code-forge run reload --run <id>\\\\n\\\",\\\"end\\\":\\\"usage: code-forge run end --run <id>\\\\n\\\"},\\\"pipeline\\\":{\\\"status\\\":\\\"usage: code-forge pipeline status [--json] [--root <dir>]\\\\n\\\",\\\"next\\\":\\\"usage: code-forge pipeline next [--json] [--root <dir>]\\\\n\\\"},\\\"outcome\\\":{\\\"seal\\\":\\\"usage: code-forge outcome seal <outcome.json> [--root <dir>]\\\\n\\\",\\\"check\\\":\\\"usage: code-forge outcome check <outcome.json> [--root <dir>] [--json]\\\\n\\\",\\\"record\\\":\\\"usage: code-forge outcome record <outcome.json> [--root <dir>] [--step <id>] [--json]\\\\n\\\"},\\\"keys\\\":{\\\"list\\\":\\\"usage: code-forge keys list\\\\n\\\",\\\"set\\\":\\\"usage: code-forge keys set <name> [--op <item-id|link|op://ref> [--cache-hours <1-24>]]\\\\n\\\",\\\"test\\\":\\\"usage: code-forge keys test <name> [--ref <ref>]\\\\n\\\",\\\"remove\\\":\\\"usage: code-forge keys remove <name>\\\\n\\\"},\\\"ledger\\\":{\\\"calibration\\\":\\\"usage: code-forge ledger calibration --slug <slug> [--question <id>]\\\\n\\\",\\\"outcome\\\":\\\"usage: code-forge ledger outcome --scan-git --slug <slug> [--cwd <dir>] [--days <n>]\\\\nusage: code-forge ledger outcome --pr <n> --ci red|green|reverted --slug <slug>\\\\n\\\",\\\"tail\\\":\\\"usage: code-forge ledger tail --slug <slug> [--n <count> | -n <count>]\\\\n\\\",\\\"add\\\":\\\"usage: code-forge ledger add coder --run <r> --block <b> --usd <n> [--note \\\\\\\"...\\\\\\\"]\\\\n\\\"},\\\"tools\\\":{\\\"install\\\":\\\"usage: code-forge tools install [<id>...] [--yes] [--dry-run]\\\\n  (install asks one yes, default no; answering no prints \\\\\\\"cancelled — nothing installed\\\\\\\" and exits 1)\\\\n\\\"},\\\"gates\\\":{\\\"detect\\\":\\\"usage: code-forge gates detect [--cwd <dir>]\\\\n\\\",\\\"run\\\":\\\"usage: code-forge gates run [--cwd <dir>] [--timeout-ms <n>] [--slug <slug>] [--run <id>] [--block <id>] [--changed]\\\\n\\\",\\\"secret-scan\\\":\\\"usage: code-forge gates secret-scan [--cwd <dir>] --file <path> [--file <path>...]\\\\n\\\",\\\"safe-edit\\\":\\\"usage: code-forge gates safe-edit [--cwd <dir>] --base <sha>\\\\n\\\",\\\"scope\\\":\\\"usage: code-forge gates scope [--cwd <dir>] --base <sha>\\\\n\\\",\\\"acceptance\\\":\\\"usage: code-forge gates acceptance --clauses <file.json> --tap <file>\\\\n\\\",\\\"transcript-grep\\\":\\\"usage: code-forge gates transcript-grep --file <path> [--cwd <dir>]\\\\n\\\"},\\\"logs\\\":{\\\"summary\\\":\\\"usage: code-forge logs summary [--days N] [--json]\\\\n\\\",\\\"clear\\\":\\\"usage: code-forge logs clear [--yes]\\\\n\\\",\\\"path\\\":\\\"usage: code-forge logs path\\\\n\\\",\\\"report\\\":\\\"usage: code-forge logs report [--last N] [--kind K] [--verb V] [--note \\\\\\\"text\\\\\\\"] [--include-warnings] [--with-doctor] [--no-ai] [--allow-old] [--force] [--dry-run] [--yes]\\\\n\\\"},\\\"proof\\\":{\\\"tier\\\":\\\"usage: code-forge proof tier --file <path> --risk <0-3> [--security] [--cwd <dir>]\\\\n\\\",\\\"export\\\":\\\"usage: code-forge proof export <block> --run <r> [--remove]\\\\n\\\",\\\"lock\\\":\\\"usage: code-forge proof lock <block> --run <r>\\\\n\\\",\\\"unlock\\\":\\\"usage: code-forge proof unlock <block> --run <r>\\\\n\\\",\\\"restore\\\":\\\"usage: code-forge proof restore <block> --run <r>\\\\n\\\",\\\"red-green\\\":\\\"usage: code-forge proof red-green <block> --run <r> --test <file[::case]> [--mechanism revert|assertion-deletion]\\\\n\\\"}}}\")
patch=['*** Begin Patch']
for p in sorted(pathlib.Path('src/cli').glob('*.mjs')):
 old=p.read_text(); new=old; verb=p.stem
 new=re.sub(r'(?m)"'^const USAGE ='"', 'export const USAGE =', new)
 if verb=='sweep':
  new=new.replace('const HELP =', 'export const USAGE =').replace('process.stdout, HELP)', 'process.stdout, USAGE)')
 if verb=='report':
  match=re.search(r\"err\\(('usage: code-forge report ["'^'"\\n]+)\\);\",new)
  new=new.replace(match.group(0),'err(USAGE);')
  new += '\\nexport const USAGE = '+match.group(1)+';\\n'
 if verb=='ledger':
  match=re.search(r\"const usage = \\(\\) => err\\(('usage: code-forge ledger calibration["'^'"\\n]+)\\);\",new)
  new=new.replace(match.group(0),'const usage = () => err(USAGE);')
  new += '\\nexport const USAGE = '+match.group(1)+';\\n'
  new=new.replace(\"\"\"err('usage: code-forge ledger add coder --run <r> --block <b> --usd <n> [--note \"...\"]\\\\n')\"\"\",\"err(SUB_USAGE.add)\")
 if verb=='gates':
  match=re.search(r'  const usage = \\(\\) =>\\n    err\\(\\n([\\s\\S]*?)\\n    \\);',new)
  new=new.replace(match.group(0),'  const usage = () => err(USAGE);')
  new += '\\nexport const USAGE =\\n'+match.group(1).rstrip().removesuffix(',')+';\\n'
 if verb=='init':
  new += \"\\nexport { USAGE } from '../install/wizard/run.mjs';\\n\"
 if verb in data['newUsage']:
  new += '\\nexport const USAGE = '+json.dumps(data['newUsage'][verb],ensure_ascii=False)+';\\n'
 new += '\\nexport const SUMMARY = '+json.dumps(data['summaries'][verb],ensure_ascii=False)+';\\n'
 if verb in data['subUsage']:
  subs=data['subUsage'][verb]
  if verb=='ledger':
   new += '\\nexport const SUB_USAGE = {\\n'
   new += ''.join('  '+json.dumps(k)+': '+json.dumps(v,ensure_ascii=False)+',\\n' for k,v in subs.items())
   new += \"  'outside-review': OUTSIDE_REVIEW_USAGE + '\\\\n',\\n};\\n\"
  else:
   new += '\\nexport const SUB_USAGE = '+json.dumps(subs,ensure_ascii=False,indent=2)+';\\n'
 if verb in ['plan','jev','context']:
  sub={'plan':'check','jev':'ask','context':'pack'}[verb]
  new += '\\nexport const SUB_USAGE = { '+sub+': USAGE };\\n'
 if verb=='autopilot':
  new += \"\\nexport const SUB_USAGE = Object.fromEntries(USAGE.trimEnd().replace('usage: code-forge autopilot ', '').split(' | ').map((line) => [line.split(' ')[0], 'usage: code-forge autopilot ' + line + '\\\\n']));\\n\"
 if verb=='block':
  new += '\\nexport const SUB_USAGE = Object.fromEntries(SUBCOMMANDS.map((sub) => [sub, verbUsage(sub)]));\\n'
 if verb=='resolve':
  new=re.sub(r'error: .usage: resolve <.*?>.', \"error: USAGE.replace('code-forge ', '').trimEnd()\", new, count=1)
 if old"'!=new:
  patch.append('"'*** Update File: '+str(p))
  patch.extend(re.sub(r'"'^@@.*@@$'"', '@@',line) for line in list(difflib.unified_diff(old.splitlines(),new.splitlines(),n=3))[2:])
patch.append('*** End Patch')
print('\\n'.join(patch))

PY"
